"""Summarize timestamped jobs for a local worker."""

from collections import Counter
from dataclasses import dataclass


@dataclass(frozen=True)
class Job:
    name: str
    status: str
    duration_ms: int


def summarize_jobs(jobs, *, slow_ms=500):
    """Aggregate status counts and return the names of slow jobs."""
    counts = Counter()
    slow = []
    total_ms = 0
    for job in jobs:
        if job.duration_ms < 0:
            raise ValueError("duration must be nonnegative")
        counts[job.status] += 1
        total_ms += job.duration_ms
        if job.duration_ms >= slow_ms:
            slow.append(job.name)
    return {
        "counts": dict(sorted(counts.items())),
        "slow": sorted(slow),
        "total_ms": total_ms,
    }

